import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2, x3 = x
    return x1**2 + x2**2 + x3**2 + 0.5 * np.cos(3.0 * x1) + 0.05 * (x1**4 - 2 * x2**4 + x3**4)

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2, x3 = x
    return np.sin(x1) + x1**2 - 0.1 * x2**3 + 0.05 * x3 + 0.01 * (x1 * x2 * x3)
